graphql.query:
mutation createQuote($input: QuoteInput!, $exposeNotAppliedDiscounts: Boolean, $inMemoryQuoteStrategy: String) {
  createQuote(
    input: $input
    exposeNotAppliedDiscounts: $exposeNotAppliedDiscounts
    inMemoryQuoteStrategy: $inMemoryQuoteStrategy
  ) {
    ...QuoteFragment
    __typename
  }
}

